// sortedKeys gives a map's keys in a stable order, so a `range` over it renders deterministically (007 §4.6).
func sortedKeys(m map[string]string) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// formLabelClasses is a label that wraps its control inside a floating form: the Design System's field label (12px,
// emphasis weight, body ink) over the control with a 4px gap. Three looks existed (an uppercase 11px label, an 11px
// caption, a 12px meta line) across the two popovers and the board card's quick edit; gap plan K-17 (2026-10-15) made them one.
func formLabelClasses(ctx context.Context) string {
	return "flex flex-col " + layoutGap(ctx, domain.GapMicro) + " " + textClass(ctx, domain.RoleMeta) + " " + weightClass(ctx, domain.WeightEmphasis) + " " + inkClass(ctx, domain.InkBody)
}

